PRAGMA foreign_keys = ON;

-- =========================
-- vehicles
-- =========================
CREATE TABLE IF NOT EXISTS vehicles (
    id TEXT NOT NULL PRIMARY KEY,  -- GUID (e.g. '6f1c1b8e-...')
    license_plate TEXT NOT NULL
        CHECK (length(license_plate) <= 20),
    brand TEXT NOT NULL
        CHECK (length(brand) <= 100),
    model TEXT NOT NULL
        CHECK (length(model) <= 100),
    manufacture_date TEXT NOT NULL -- ISO-8601 datetime string recommended
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_vehicles_license_plate
ON vehicles (license_plate);

-- =========================
-- customers
-- =========================
CREATE TABLE IF NOT EXISTS customers (
    id TEXT NOT NULL PRIMARY KEY,  -- GUID
    document_id TEXT NOT NULL
        CHECK (length(document_id) <= 15),
    name TEXT NOT NULL
        CHECK (length(name) <= 50),
    surname TEXT NOT NULL
        CHECK (length(surname) <= 100)
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_customers_id_document
ON customers (document_id);

-- =========================
-- rental_history
-- =========================
CREATE TABLE IF NOT EXISTS rental_history (
    id TEXT NOT NULL PRIMARY KEY,  -- GUID
    customer_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    start_date TEXT NOT NULL,
    end_date TEXT NULL,

    -- End date can't be before start date
    CHECK (end_date IS NULL OR end_date >= start_date),

    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT
);

-- Helpful indexes for lookups
CREATE INDEX IF NOT EXISTS ix_rental_history_vehicle
ON rental_history (vehicle_id);

CREATE INDEX IF NOT EXISTS ix_rental_history_customer
ON rental_history (customer_id);

-- Enforce: one active rent per customer (end_date IS NULL)
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_history_customer_open
ON rental_history (customer_id)
WHERE end_date IS NULL;

-- Enforce: one active rent per vehicle (end_date IS NULL)
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_history_vehicle_open
ON rental_history (vehicle_id)
WHERE end_date IS NULL;

